  const savedTurns=(visual?.contextTurns??(history.length?[]:savedThreadTurns(this.p,conversation.threadId))).filter(turn=>!turn.threadId||turn.threadId===conversation.threadId).map(turn=>({question:turn.question,messages:(turn.messages||[]).filter(m=>['user','assistant'].includes(m.role)).map(m=>({role:m.role,text:m.text})),snapshotRevision:turn.snapshotRevision,...(turn.reference?.kind==='program_flow'?{reference:programFlowAgentReference(turn.reference)}:{})}));
