  try{await this.wire({type:'prompt',id:this.turn,message,images,...(this.runtime?.activeAdapter?.id==='codex'&&text.trim().startsWith('/')?{native_command:text.trim()}:{}),session_key:`${this.sessionNamespace}:${epoch}:${conversation.threadId}`,thread_id:conversation.threadId,project_key:this.p.data.visualInquiry?.boards?.[0]?.id||null,parent_thread_id:conversation.parentThreadId,parent_turn_id:conversation.parentTurnId,saved_history_count:history.length+savedTurns.length+parentHistory.length});for(const key of imageKeys)this.sentVisualKeys.add(key);while(this.sentVisualKeys?.size>128)this.sentVisualKeys.delete(this.sentVisualKeys.values().next().value);}catch(e){this.turnError('SEND_FAILED',e.message);this.busy=false;this.turn=null;this.turnReference=null;this.turnVisualBoardId=null;this.ui.activity('');this.record('system','傳送失敗：'+e.message);throw e}
